const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[80,"REST",0,1],[96,"A",0,1],[112,"A",0,1],[128,"A",0,1],[144,"A",0,1],[160,"A",0,1],[176,"A",0,1],[192,"REST",0,1],[224,"REST",0,1],[240,"A",1,1],[256,"A",1,1],[272,"A",1,1],[288,"A",1,1],[304,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[48,"B",0,1],[80,"RUN",0,1],[96,"REST",0,1],[192,"BRIDGE",0,1],[208,"BRIDGE",0,1],[224,"RUN",0,1],[240,"REST",0,1],[304,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[80,"REST",0,1],[96,"REST",0,1],[192,"REST",0,1],[224,"REST",0,1],[240,"HARMONY",0,1],[304,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- supersaw ----------------------------------------------------------------------------------
const track0 = {
  color: '#ffffff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["y = \\Rev\\Big[0.5\\,d(t_k)\\,\\LP_{7000}\\big(\\SS_7(f) + 0.5\\,\\SS_5(2f)\\big)\\Big],\\qquad f = 261.63\\cdot 2^{n/12}\\ \\text{(портаменто 18 мс)}","d(t_k) = 1 - 0.7\\big(1 - t_k/0.18\\big)^2\\ \\text{(сайдчейн от бочки в дропах)}"],
  audio() {
    const main = supersaw({ voices: 7, detune: 0.27, seed: 3 }), oct = supersaw({ voices: 5, detune: 0.21, seed: 5 })
    const lpL = filter('lp'), lpR = filter('lp'), gate = smooth(6), glide = smooth(18), fx = reverb({ room: 0.88, wet: 0.4 })
    let n = 0
    return x => {
      const m = leadAt(x)
      if (m) n = m.n
      const a = 0.45 * gate(m && m.u < 0.92 ? 1 : 0) * pumpAt(x), f = glide(hz(n, C4))
      const [l1, r1] = main(f), [l2, r2] = oct(2 * f)
      return fx(a * lpL(l1 + 0.5 * l2, 7000, 0.8), a * lpR(r1 + 0.5 * r2, 7000, 0.8))
    }
  },
}

// ---- pluck -------------------------------------------------------------------------------------
const track1 = {
  color: '#7ff5d0',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Pl = \\Rev\\,\\Dly_{3/4}\\Big[\\sum_{k}\\tfrac{v}{k}\\,e^{-t(2.2 + 1.1k(1.3 - 0.6v))}\\big(\\sin 2\\pi kft + \\sin(2\\pi\\,1.004kft + k)\\big)\\Big]\\quad\\text{— пила, чей фильтр захлопывается: гармоника } k \\text{ гаснет со скоростью } \\propto k"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(pluckTone, { release: 0.12, life: 2.5, max: 16 }), fire = trigger()
    const echo = delay({ time: sec * 0.75, feedback: 0.38, wet: 0.3 }), verb = reverb({ room: 0.86, damp: 0.4, wet: 0.3 })
    return x => {
      const m = lead2At(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.75 + 0.2 * hash(floor(4 * x), 9), m.d * sec)
      return verb(...echo(...pan(0.936 * p() * pumpAt(x), -0.3)))
    }
  },
}

